<?php
require_once ROOT_PATH.'core/Controller.php';
require_once APP_PATH.'Models/EmployeeCertification.php';
require_once APP_PATH.'Models/Notification.php';
require_once APP_PATH.'Models/Employee.php';

class CertificationController extends Controller {
    private EmployeeCertification $certifications;private Notification $notifications;
    public function __construct(){$this->certifications=new EmployeeCertification();$this->notifications=new Notification();}

    public function index(){
        Auth::requireAuth();$admin=Auth::isHR();$changes=$admin?$this->certifications->refreshStatuses():[];
        foreach($changes as $change){$title=$change['new_status']==='Expired'?'Certification expired':'Certification expiring soon';$message=$change['certification_name'].' is '.$change['new_status'].'.';$this->notifications->createForEmployee($change['employee_id'],$title,$message,'warning','index.php?page=certifications','certifications',$change['id']);$this->notifications->createForAdmins($title,$message,'warning','index.php?page=certifications','certifications',$change['id']);AuditLogger::log('CERTIFICATION_'.strtoupper(str_replace(' ','_',$change['new_status'])),'Employee Certifications',$message,null,['record_type'=>'employee_certification','record_id'=>$change['id'],'old_value'=>['status'=>$change['status']],'new_value'=>['status'=>$change['new_status']]]);}
        $employeeId=$admin?null:Auth::employeeId();$code=strtoupper(preg_replace('/[^A-F0-9]/','',(string)($_GET['verification_code']??'')));$verification=null;if($code!==''){$verification=$this->certifications->verifyCode($code,$employeeId);if($verification)AuditLogger::log('CERTIFICATE_VERIFIED','Employee Certifications','Verified certificate '.$verification['certificate_number'].' using its internal verification code.',null,['record_type'=>'employee_certification','record_id'=>$verification['id']]);}
        $this->view('certifications/index',['is_admin'=>$admin,'certifications'=>$this->certifications->records($employeeId),'employees'=>$admin?(new Employee())->getAllWithDetails():[],'trainings'=>$admin?$this->certifications->db->fetchAll('SELECT id,title FROM training_courses ORDER BY title'):[],'warning_days'=>$this->certifications->warningDays(),'verification_code'=>$code,'verification_result'=>$verification]);
    }

    public function save(){
        $this->adminPost();$id=(int)($_POST['id']??0);$old=$id?$this->certifications->record($id):null;if($id&&!$old)$this->json('error','Certification not found.',[],404);
        try{$employee=(int)($_POST['employee_id']??0);$name=sanitize_input($_POST['certification_name']??'');$type=sanitize_input($_POST['certification_type']??'');$status=sanitize_input($_POST['status']??'Pending Verification');$issue=$this->date($_POST['issue_date']??'');$expiry=$this->date($_POST['expiration_date']??'');$training=(int)($_POST['related_training_id']??0);
            if(!$this->certifications->db->fetchOne('SELECT id FROM employees WHERE id=?',[$employee])||$name===''||$type==='')throw new RuntimeException('Employee, certification name, and type are required.');
            if(!in_array($status,EmployeeCertification::STATUSES,true))throw new RuntimeException('Select a valid certification status.');if($issue&&$expiry&&$expiry<$issue)throw new RuntimeException('Expiration date cannot be earlier than issue date.');if($training&&!$this->certifications->db->fetchOne('SELECT id FROM training_courses WHERE id=?',[$training]))throw new RuntimeException('Select a valid related training.');
            $data=['employee_id'=>$employee,'certification_name'=>$name,'certification_type'=>$type,'issuing_organization'=>sanitize_input($_POST['issuing_organization']??'')?:null,'issue_date'=>$issue,'expiration_date'=>$expiry,'status'=>$status,'related_training_id'=>$training?:null,'created_by'=>$old['created_by']??Auth::user()['id']];if(!in_array($status,['Pending Verification','Revoked'],true)){$data['verified_by']=$old['verified_by']??Auth::user()['id'];$data['verification_date']=$old['verification_date']??date('Y-m-d H:i:s');}
            if($file=$this->upload())$data['supporting_file']=$file;$recordId=$id; if($id)$this->certifications->update($id,$data);else $recordId=(int)$this->certifications->create($data);
            AuditLogger::log($id?'UPDATE_CERTIFICATION':'CREATE_CERTIFICATION','Employee Certifications',($id?'Updated':'Created').' certification '.$name,null,['record_type'=>'employee_certification','record_id'=>$recordId,'old_value'=>$old,'new_value'=>$data]);$this->json('success','Certification record saved.',['id'=>$recordId]);
        }catch(Throwable $e){$this->json('error',$e->getMessage(),[],422);}
    }

    public function verify(){
        $this->adminPost();$id=(int)($_POST['id']??0);$row=$this->certifications->record($id);if(!$row)$this->json('error','Certification not found.',[],404);$status=sanitize_input($_POST['status']??'Valid');if(!in_array($status,['Valid','Revoked'],true))$this->json('error','Invalid verification decision.',[],422);
        $this->certifications->update($id,['status'=>$status,'verified_by'=>Auth::user()['id'],'verification_date'=>date('Y-m-d H:i:s')]);$this->notifications->createForEmployee($row['employee_id'],'Certification '.$status,$row['certification_name'].' was marked '.$status.'.',$status==='Valid'?'success':'warning','index.php?page=certifications','certifications',$id);AuditLogger::log($status==='Revoked'?'CERTIFICATION_REVOKED':'CERTIFICATION_VERIFIED','Employee Certifications','Certification ID '.$id.' marked '.$status,null,['record_type'=>'employee_certification','record_id'=>$id,'old_value'=>['status'=>$row['status']],'new_value'=>['status'=>$status,'verified_by'=>Auth::user()['id']]]);$this->json('success','Certification marked '.$status.'.');
    }

    public function download(){Auth::requireAuth();$row=$this->certifications->record((int)($_GET['id']??0));if(!$row||!$row['supporting_file']){http_response_code(404);exit('Certification file not found.');}Auth::requireOwnership($row['employee_id']);if($row['supporting_file']==='generated'&&$row['related_training_registration_id'])redirect(BASE_URL.'?page=training_certificate&id='.(int)$row['related_training_registration_id']);$root=realpath(ROOT_PATH.'public/uploads/training');$path=realpath(ROOT_PATH.'public/'.str_replace(['/',chr(92)],DIRECTORY_SEPARATOR,ltrim($row['supporting_file'],'/'.chr(92))));if(!$root||!$path||!is_file($path)||strpos($path,$root.DIRECTORY_SEPARATOR)!==0){http_response_code(404);exit('File not found.');}$ext=pathinfo($path,PATHINFO_EXTENSION);header('Content-Type:'.(mime_content_type($path)?:'application/octet-stream'));header('Content-Disposition:attachment; filename="certification-'.$row['id'].'.'.$ext.'"');header('X-Content-Type-Options:nosniff');readfile($path);exit;}
    private function adminPost(){Auth::requirePermission('manage_training');Auth::requireMethod('POST');if(!verify_csrf_token($_POST['csrf_token']??''))$this->json('error','Invalid CSRF token.',[],403);}
    private function date($value){if($value==='')return null;$d=DateTime::createFromFormat('Y-m-d',$value);if(!$d||$d->format('Y-m-d')!==$value)throw new RuntimeException('Enter valid dates.');return $value;}
    private function upload(){if(!isset($_FILES['supporting_file'])||$_FILES['supporting_file']['error']===UPLOAD_ERR_NO_FILE)return null;$f=$_FILES['supporting_file'];if($f['error']!==UPLOAD_ERR_OK||$f['size']<1||$f['size']>5*1024*1024)throw new RuntimeException('Supporting file must be a PDF or image up to 5 MB.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['pdf','jpg','jpeg','png'],true))throw new RuntimeException('Supporting file must be PDF, JPG, or PNG.');$dir=ROOT_PATH.'public/uploads/training/certifications/';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Unable to prepare upload storage.');$name=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.$name))throw new RuntimeException('Unable to save supporting file.');return 'uploads/training/certifications/'.$name;}
}
